import json,pathlib
P='supporting_page_checked';M='bibliographic_metadata_checked'
def src(t,u,status,n):return[t,u,status,n]
def w(y,t,s=0,n='Dated publication listed in the consulted bibliography; body unread.'):return[y,t,s,n]
def e(t,r,n,s=0,k='contribution'):return[t,r,n,s,k]
d=[]
d.append(dict(description='A Canadian intellectual and social historian whose work connects ideas about western expansion, the state and postwar generational change. His baby-boom synthesis treats childhood, consumer power and youth politics together; the reader used here disputes how representative its radical youth are.',sources=[src('UBC: Doug Owram bibliography','https://hs.ok.ubc.ca/about/contact/doug-owram/',M,'Institutional profile and selected publication dates read. Undated emeritus listing is insufficient current life-status evidence.'),src('Daniel Stoffman, “Boomers: Suchness or Muchness?”, Books in Canada','https://www.booksincanada.com/article_view.asp?id=223',P,'Complete substantive review read. Stoffman describes childhood/psychology/consumer culture and the 1960s argument, while challenging radical representativeness and aspects of the cohort explanation. Monograph unread.')],works=[w(1980,'Promise of Eden'),w(1985,'The Government Generation'),w(1996,'Born at the Right Time')],edges=[e('cdn_childhood_youth','Relates the baby boom to child-centred households, consumer markets and psychological ideas about childhood.','Daniel Stoffman describes these arguments in his substantive review; this is named-reader mediation, not a reading of the whole book. He questions how distinctive the cohort itself was.',1),e('cdn_sixties','Interprets Canadian youth politics through the scale and shared culture of the baby-boom generation.','Stoffman reports the interpretation but disputes the space given to radicals and the claim of broad generational sympathy. The qualification is part of this contribution record.',1)]))
d.append(dict(description='A Canadian historian of gender, migration and class. Gatekeepers investigates how everyday institutions tried to reshape newcomers in Cold War Canada, while keeping immigrant responses and inequalities in view. Her editorial collaborations retain their joint credit.',sources=[src('Franca Iacovetta, University of Toronto Culinaria profile','https://utsc.utoronto.ca/culinaria/franca-iacovetta-0',M,'Research identity, 2006 Gatekeepers and editorial publications checked. Page retains a 2014 conference announcement; not recent living evidence.'),src('Tanya Basok and Marshall Bastable, “Knock, Knock, Knockin’ on Heaven’s Door”, Labour/Le Travail 63 (2009), 207–219','https://www.lltjournal.ca/index.php/llt/article/download/5564/6411',P,'Complete review essay read; Iacovetta discussion especially 209–214. Reviewers analyze surveillance, liberal citizenship, gender/family and immigrant accommodation/resistance, and question the scope of exclusion. Other books in this joint review are not attributed to Iacovetta.'),src('York University Elia Chair: Italian-Canadian studies bibliography','https://elia-chair.info.yorku.ca/italian-canadian-studies-bibliography/',M,'1992 Such Hardworking People and 2000 Enemies Within checked; Enemies Within is co-edited with Roberto Perin and Angelo Principe, not solely authored.')],works=[w(1992,'Such Hardworking People',2),w(2000,'Enemies Within (co-edited with Roberto Perin and Angelo Principe)',2),w(2006,'Gatekeepers')],edges=[e('cdn_immigration_ethnicity','Examines everyday gatekeeping and the contested remaking of immigrant citizenship in Cold War Canada.','Basok and Bastable’s substantive reading of Gatekeepers supports this scoped claim, including immigrant negotiation/resistance; it is not full-book verification.',1),e('cdn_women_gender','Places gendered expectations about marriage, family and sexuality inside the regulation of newcomers.','The same review’s treatment of Gatekeepers makes these mechanisms substantive, rather than inferring a gender arrow from Iacovetta’s appointment.',1)]))
d.append(dict(description='A historian of Africa, labour and empire who tests large concepts against changing and unequal relationships. His interview distinguishes colonial power from total domination and imperial citizenship from an assumed national endpoint.',sources=[src('Frederick Cooper, Human Centered interview and linked bibliography, CASBS','https://human-centered.simplecast.com/episodes/fred-cooper-illumination-of-history-E3sEgFhZ',P,'Transcript read, especially genealogy, concepts, sequences and imperial citizenship sections; audio not used. Episode notes date 1996, 2005 and 2010 books. Empires in World History is coauthored with Jane Burbank. This is an account of his research, not a reading of the monographs.')],works=[w(1996,'Decolonization and African Society'),w(2005,'Colonialism in Question'),w(2010,'Empires in World History (with Jane Burbank)')],edges=[e('africanhist','Studies African labour and exploitation without assuming universal proletarianization.','Cooper’s opening autobiographical answers distinguish post-slavery labour, land and uneven colonial power.'),e('global','Treats empire and citizenship relationally across scales and alternative political possibilities.','The interview’s citizenship and historical-sequences answers warn against reading national outcomes backwards. Coauthored books retain Jane Burbank’s credit.')]))
d.append(dict(description='A historian of emancipation and Reconstruction who places Black political action, contested freedom and federal enforcement at the centre of United States history. He explicitly identifies Du Bois’s account of Reconstruction as a resource while distinguishing war’s destructiveness from emancipation’s consequences.',sources=[src('Eric Foner, author biography and bibliography','https://www.ericfoner.com/',M,'Author biography and dated book list checked:1970Free Soil,1988Reconstruction,1998Story. Columbia directory separately confirms identity but its work list lacks dates; no full-book reading.'),src('Eric Foner, “Struggle and Progress”, Jacobin interview, summer 2015','https://www.ericfoner.com/articles/summer2015jacobin.html',P,'Complete written interview read, especially Civil War, Du Bois, freedom and Reconstruction enforcement answers. Author-hosted copy. Interview is 2015, not recent life evidence.')],works=[w(1970,'Free Soil, Free Labor, Free Men'),w(1988,'Reconstruction: America’s Unfinished Revolution'),w(1998,'The Story of American Freedom')],edges=[e('black','Interprets Reconstruction through Black political action, contested freedom and the struggle to build democracy.','Own interview answers stress change after slavery and oppose treating later injustice as proof that emancipation changed nothing.',1),e('w_e_b_du_bois','Explicitly draws on Du Bois’s account of emancipation and Reconstruction as struggles over democracy.','For influence the source endpoint must be Du Bois: this outgoing proposal is a contribution to the Du Bois reception record, not an assertion Foner influenced Du Bois. Root should retain contribution classification and the temporal qualification.',1)],scope='The Du Bois relationship records Foner’s explicit later engagement, not reverse chronological influence.'))
d[-1]['edges'][1]=e('intellectualhistory','Traces competing meanings of freedom rather than treating freedom as one stable national possession.','In the interview Foner explicitly contrasts economic equality and rights with narrow anti-government definitions, and rejects narratives that absorb every struggle into a stable Americanism.',1)
d.append(dict(description='A historian of American ideas and transatlantic social politics. His Age of Fracture account follows the fragmentation of social thought across disciplines and policy, including the move from institutions and interdependence toward choice and flexible selves.',sources=[src('Daniel T. Rodgers, “Age of Fracture”, Rorotoko, 30 March 2011','https://www.rorotoko.com/micro-interviews/20110330-daniel-rodgers-on-age-of-fracture-1-1',P,'Author’s complete “In a nutshell” statement and biography read. Biography dates Contested Truths 1987, Atlantic Crossings 1998, Age of Fracture 2011. Biography’s 1976 Work Ethic date conflicts with Princeton’s 1978; that work is omitted from chronology rather than silently resolved.'),src('Daniel T. Rodgers with Jonny Gordon-Farleigh, “Atlantic Crossings” interview, Winter 2026 #52','https://www.stirtoaction.com/articles/atlantic-crossings',P,'Interview opening and first answer inspected for 1998 work identity and dated 2026 participation; rest not used for substantive edges.')],works=[w(1987,'Contested Truths'),w(1998,'Atlantic Crossings'),w(2011,'Age of Fracture')],edges=[e('intellectualhistory','Tracks the late-twentieth-century fragmentation of ideas about markets, society, identities and historical constraint.','Author’s 2011 account specifies intellectual arguments and changing categories; not simply a party-political change.'),e('political','Links shifting concepts of obligation and choice to arguments over social provision and public policy.','Rorotoko statement expressly connects fracturing thought to school choice, safety nets, affirmative action and war; policy examples are his interpretations.')],life=dict(status='living',sources=[(1,'Winter 2026 #52 interview opening and DTR first answer','Positive recent first-person interview by the Atlantic Crossings historian; excludes financial educator Daniel C. Rodgers.')],limits='Dated 2026 interview supports living status as checked; no lifespan or career interval inferred.')))
d.append(dict(description='A historian of Britain and empire whose gender-history intervention treats sexual difference as something produced and managed in historical circumstances. Her account connects gender to slavery, capitalism and empire while distinguishing gender history from simply adding women to existing narratives.',sources=[src('Antoinette Burton, Illinois interview on Gender History, 8 August 2024','https://history.illinois.edu/news/2024-08-08/illinois-historians-book-provides-introduction-gender-history-interview-professor',P,'Complete short university written interview read. Quotes on gender history versus women’s history and gendered slavery/empire support the bounded relationships; monographs unread.'),src('UNC Press: Burdens of History','https://uncpress.org/9780807844717/burdens-of-history/',M,'Publisher title, author and November 1994 publication checked; promotional summary not used as primary argument evidence.'),src('Duke University Press: After the Imperial Turn','https://dukeupress.edu/after-the-imperial-turn',M,'May 2003 publication and Burton editorial credit checked. Contributors keep ownership of their own essays.')],works=[w(1994,'Burdens of History',1),w(2003,'After the Imperial Turn (edited collection)',2),w(2024,'Gender History: A Very Short Introduction',0)],edges=[e('gender','Distinguishes gender history’s analysis of produced sexual difference from recovery of women’s participation alone.','Own university interview explicitly makes the methodological distinction.'),e('post','Connects historical gender categories and divisions of labour to slavery and imperial power.','Own interview explains this specific connection; no blanket claim that every empire shared an identical gender regime.')],life=dict(status='living',sources=[(0,'8 August 2024 written interview','Positive dated first-person scholarly interview, with Illinois director and author identity.')],limits='2024 positive interview supports a dated living classification; no later life event inferred.')))
d.append(dict(description='A historian of American political culture whose interpretations moved from economic-interest explanations toward ideas, status anxieties and political irrationality. Eric Foner’s retrospective distinguishes his critical account of consensus from celebratory consensus history and also identifies its limits.',sources=[src('Columbia C250: Richard Hofstadter (1916–1970)','https://www.c250.columbia.edu/c250_celebrates/remarkable_columbians/richard_hofstadter.html',M,'Institutional memorial title and biography establish historian identity and death year 1970; no day-level claim.'),src('Eric Foner, “Richard Hofstadter: Columbia’s Evolutionary Historian”, Columbia Magazine','https://magazine.columbia.edu/article/richard-hofstadter-columbias-evolutionary-historian',P,'Complete substantive retrospective read. Foner was his student; discusses 1944, 1948, 1955 works, changing relation to Beard and consensus, intellectual influences and criticism of the Populist/Progressive interpretation. Hofstadter monographs unread.')],works=[w(1944,'Social Darwinism in American Thought',1),w(1948,'The American Political Tradition',1),w(1955,'The Age of Reform',1)],edges=[e('progressive','Critically reworks the economic-conflict interpretation and explores ideological consensus in American politics.','Foner distinguishes Hofstadter’s critical consensus interpretation from celebratory versions and notes the later reconsideration of conflict.',1),e('political','Brings status anxiety, symbols and irrationality into accounts of political culture.','Foner’s named substantive reading also judges the treatment of Populists and Progressives exaggerated and elitist in important respects. This qualification survives the contribution arrow.',1)],life=dict(status='deceased',death_year=1970,death_precision='year',sources=[(0,'Memorial heading “1916–1970”','Explicit death year and Columbia historian identity.')],limits='Year checked; no precise death date supplied.')))
d.append(dict(description='A labour historian who studies the historical making of whiteness and its consequences for worker solidarity. His interview explicitly acknowledges Du Bois and relates emancipation to a broader history of labour freedom without claiming race explains all working-class conservatism.',sources=[src('David Roediger interviewed by Al Hart, UE, 1 February 2012','https://www.ueunion.org/ue-news-feature/2012/race-and-the-working-class-an-interview-with-david-roediger',P,'Complete written union interview read; Du Bois acknowledgment, emancipation and eight-hour day, white-worker identity and qualifications to political explanation.'),src('David Roediger author bibliography: The Wages of Whiteness','https://www.davidroediger.org/books/the-wages-of-whiteness.php',M,'Author’s publication bibliography gives first Verso edition 1991; later preface/reprint not substituted.'),src('UC Press: Colored White','https://www.ucpress.edu/books/colored-white/pdf',M,'Publisher metadata gives May 2002; other cited works not treated as jointly authored by Roediger.'),src('David Roediger author bibliography: Working Toward Whiteness','https://www.davidroediger.org/books/working-toward-whiteness.php',M,'Author bibliography explicitly identifies New York:Basic Books,2005andISBN9780465070749. Hachette9780786722105is a2006ebook with2018introdescription and cannot date the original. Whole book unread.')],works=[w(1991,'The Wages of Whiteness',1),w(2002,'Colored White',2),w(2005,'Working Toward Whiteness',3)],edges=[e('labourhistory','Relates emancipation and the eight-hour movement to broader struggles over labour freedom.','Own interview credits Du Bois’s general-strike interpretation; no claim that emancipation mechanically caused every later labour development.'),e('racial_formation','Examines white-worker identity as historically constructed and as a constraint on class solidarity.','Own interview distinguishes historical racialization from natural race and explicitly denies race explains everything about labour conservatism.')]))
d.append(dict(description='A historian of sensory worlds and the socially overlooked. His interview explains how bells, smells and desired landscapes become historical objects, and why recovering an unknown rural person requires a different experiment from a biography built on self-authored testimony.',sources=[src('Alain Corbin interviewed by Ivan Jablonka, “L’histoire entre rêve et plaisir”, La Vie des idées, 8 November 2013','https://laviedesidees.fr/L-histoire-entre-reve-et-plaisir',P,'Complete French transcript and bibliographic introduction read; video not used. Interview discusses sensory history, bells and Pinagot. Original French publication dates retained; English translations are not substituted.')],works=[w(1978,'Les Filles de noce'),w(1982,'Le Miasme et la Jonquille'),w(1998,'Le Monde retrouvé de Louis-François Pinagot')],edges=[e('culture','Makes changing sensory experience—smells, bells and desires—a historical question.','Own interview expressly declines exclusive priority and situates the questions in wider historiographical circumstances.'),e('micro','Experiments with recovering the world of a person who left no self-authored archive.','Own account of Pinagot explains the wish to recover an unknown individual; reconstructed context is not that person’s recorded inner voice.')]))
d.append(dict(description='A historian of American slavery who interrogates the categories historians use to describe enslaved people. “On Agency” argues that treating the discovery of agency as the culmination of slavery history can reproduce liberal assumptions and obstruct attention to historically specific human experience.',sources=[src('Walter Johnson, “On Agency”, Journal of Social History 37.1 (2003), 113–124','https://glc.yale.edu/sites/default/files/pdf/on_agency_johnson.pdf',P,'Complete twelve-page article read. Critique of agency/resistance equivalence and liberal selfhood is methodological; does not deny enslaved people acted or resisted.'),src('Harvard African and African American Studies: Walter Johnson','https://aaas.fas.harvard.edu/people/walter-johnson',M,'Institutional identity and dates Soul by Soul 1999 and River of Dark Dreams 2013 checked. Directory uses a variant River subtitle; chronology uses the published title corroborated by Harvard Press/JSTOR.')],works=[w(1999,'Soul by Soul',1),w(2003,'“On Agency”',0,'Article masthead: autumn 2003, Journal of Social History 37.1, 113–124.'),w(2013,'River of Dark Dreams: Slavery and Empire in the Cotton Kingdom',1)],edges=[e('social','Questions histories that make recovering agency the endpoint of interpreting slavery.','Read article, especially opening problem and closing methodological discussion; criticism is of an analytic habit rather than of enslaved action itself.',0,'critique'),e('black','Calls for historically specific accounts of enslaved humanity, action and collective life beyond the agency/resistance formula.','Read article’s distinction between humanity and agency, with its caution about liberal notions of autonomous selfhood. This is a methodological contribution to slavery history, not a claim every case has been independently verified.')]))
pathlib.Path(__file__).with_name('research-config.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
